{{-- Slideshows V2 Component - Carousel de galerie vidéo --}}
{{-- Utilise la modal ViewingCarousel pour la lecture vidéo --}}
<section class="slideshows-v2-section">
    <div class="container">
        <div class="slideshows-v2-container">
            <div class="slideshows-v2-track" id="slideshowsV2Track">
                {{-- Les slides seront générés dynamiquement par JavaScript --}}
            </div>
        </div>
        
        <div class="slideshows-v2-nav">
            <button class="slideshows-v2-nav-btn" id="slideshowsV2PrevBtn">
                <i class="fas fa-chevron-left"></i>
            </button>
            <div class="slideshows-v2-dots" id="slideshowsV2Dots">
                {{-- Les points de navigation seront générés dynamiquement --}}
            </div>
            <button class="slideshows-v2-nav-btn" id="slideshowsV2NextBtn">
                <i class="fas fa-chevron-right"></i>
            </button>
        </div>
    </div>
</section>
